import { PGlite } from "@electric-sql/pglite";
import { drizzle } from "drizzle-orm/pglite";
import { migrate } from "drizzle-orm/pglite/migrator";
import type { Database } from "./client";
import * as schema from "./schema";

/** Migrations generated by `pnpm db:generate`, relative to `apps/api` (the scripts' cwd). */
export const MIGRATIONS_FOLDER = "./drizzle";

export type PgliteDb = {
  db: Database;
  client: PGlite;
  close: () => Promise<void>;
};

/**
 * Postgres in WASM, for tests (in memory) and local development (persisted to `dataDir`),
 * so nobody needs a Neon account to run the API. Never imported by the Worker entry.
 */
export async function createPgliteDb(
  options: { dataDir?: string; migrationsFolder?: string } = {},
): Promise<PgliteDb> {
  const client = new PGlite(options.dataDir);
  const db = drizzle({ client, schema });
  await migrate(db, { migrationsFolder: options.migrationsFolder ?? MIGRATIONS_FOLDER });
  return { db, client, close: () => client.close() };
}
